func (s *Service) forkWatcher() {
	if s.dv5Listener == nil {
		return
	}
	slotTicker := slots.NewSlotTicker(s.genesisTime, params.BeaconConfig().SecondsPerSlot)
	var scheduleEntry params.NetworkScheduleEntry
	for {
		select {
		case currSlot := <-slotTicker.C():
			currentEpoch := slots.ToEpoch(currSlot)
			newEntry := params.GetNetworkScheduleEntry(currentEpoch)
			if newEntry.ForkDigest != scheduleEntry.ForkDigest {
				nextEntry := params.NextNetworkScheduleEntry(currentEpoch)
				if err := updateENR(s.dv5Listener.LocalNode(), newEntry, nextEntry); err != nil {
					log.WithFields(newEntry.LogFields()).WithError(err).Error("Could not add fork entry")
					continue
				}
				scheduleEntry = newEntry
			}
		case <-s.ctx.Done():
			slotTicker.Done()
			return
		}
	}
}

func (dv *RODataColumnsVerifier) ValidProposerSignature(ctx context.Context) (err error) {
	if ok, err := dv.results.cached(RequireValidProposerSignature); ok {
		return err
	}
	defer dv.recordResult(RequireValidProposerSignature, &err)
	for _, dataColumn := range dv.dataColumns {
		signatureData := columnToSignatureData(dataColumn)
		seen, err := dv.sc.SignatureVerified(signatureData)
		if err != nil {
			columnVerificationProposerSignatureCache.WithLabelValues("hit-invalid").Inc()
			return columnErrBuilder(ErrInvalidProposerSignature)
		}
		if seen {
			columnVerificationProposerSignatureCache.WithLabelValues("hit-valid").Inc()
			continue
		}
		parentState, err := dv.parentState(ctx, dataColumn)
		if err != nil {
			return columnErrBuilder(errors.Wrap(err, "parent state"))
		}
		if err = dv.sc.VerifySignature(signatureData, parentState); err != nil {
			return columnErrBuilder(errors.Wrap(err, "verify signature"))
		}
	}
	return nil
}

// Three requirement sets:
// GossipDataColumnSidecarRequirements (12 checks): full suite
// ByRangeRequestDataColumnSidecarRequirements (3 checks): ValidFields + InclusionProven + KzgProofVerified
// ByRootRequestDataColumnSidecarRequirements (3 checks): ValidFields + InclusionProven + KzgProofVerified

// SatisfyRequirement bypass mechanism:
func (dv *RODataColumnsVerifier) SatisfyRequirement(req Requirement) {
	dv.recordResult(req, nil)
}

// Usage in validateDataColumn (sync package) after batch KZG:
verifier.SatisfyRequirement(verification.RequireSidecarKzgProofVerified)

// Actual validation ordering in validateDataColumn:
// 1. ValidFields()                     - REJECT - O(fields) cheap
// 2. CorrectSubnet()                   - REJECT - O(1) cheap
// 3. NotFromFutureSlot()               - IGNORE - O(1) cheap
// 4. SlotAboveFinalized()              - IGNORE - O(1) cheap
// 5. SidecarParentSeen()               - IGNORE - O(cache) medium
// 6. SidecarParentValid()              - REJECT - O(cache) cheap
// 7. ValidProposerSignature()          - REJECT - O(BLS) EXPENSIVE ~2-5ms
// 8. SidecarParentSlotLower()          - REJECT - O(1) cheap
// 9. SidecarDescendsFromFinalized()    - REJECT - O(cache) medium
// 10. SidecarInclusionProven()         - REJECT - O(merkle) medium
// 11. validateWithKzgBatchVerifier()   - REJECT - O(KZG) MOST EXPENSIVE
// 12. hasSeenDataColumnIndex()         - IGNORE - O(cache) cheap  ← CRITICAL ORDERING BUG
// 13. SidecarProposerExpected()        - REJECT - O(shuffling) expensive

// hasSeenDataColumnIndex FIRES AFTER KZG (position 12 vs 11)
// Replay of accepted sidecar triggers full KZG verification before dedup detection

func (dv *RODataColumnsVerifier) SidecarProposerExpected(ctx context.Context) (err error) {
	// targetRootFromCache: caches targetRoot by (slot, parentRoot)
	// dataColumnEpoch = slots.ToEpoch(slot) - 1 (if epoch > 0)
	for _, dataColumn := range dv.dataColumns {
		dataColumnSlot := dataColumn.Slot()
		parentRoot := dataColumn.ParentRoot()
		targetRoot, err := targetRootFromCache(dataColumnSlot, parentRoot)
		...
		checkpoint := &forkchoicetypes.Checkpoint{Root: targetRoot, Epoch: dataColumnEpoch}
		idx, cached := dv.pc.Proposer(checkpoint, dataColumnSlot)
		if !cached {
			parentState, err := dv.parentState(ctx, dataColumn)
			idx, err = dv.pc.ComputeProposer(ctx, parentRoot, dataColumnSlot, parentState)
		}
		if idx != dataColumn.ProposerIndex() {
			return columnErrBuilder(errSidecarUnexpectedProposer)
		}
	}
	return nil
}
